function translatedFromEnglish(locale: string, source: Record<LegalDocumentKey, LegalDocument>, labels: Record<LegalDocumentKey, { title: string; description: string; headings: string[]; paragraphs: LocalizedText[] }>, eyebrow: string, updated: string): Record<LegalDocumentKey, LegalDocument> {
  return (Object.keys(source) as LegalDocumentKey[]).reduce((documents, key) => {
    const paragraphs = source[key].sections.map((section, index) => labels[key].paragraphs[index] ?? [fallbackParagraph(locale, key, index, labels[key].headings[index] ?? section.title)]);
    documents[key] = localizedDocument(source[key], { eyebrow, title: labels[key].title, description: labels[key].description, locale, updated, headings: labels[key].headings, paragraphs });
    return documents;
  }, {} as Record<LegalDocumentKey, LegalDocument>);
}

