export const LEGAL_DOCUMENTS: Record<LegalLocale, Record<LegalDocumentKey, LegalDocument>> = {
  fr: FR,
  en: EN,
  it: IT,
  es: ES,
  nl: NL,
  no: NO,
  ar: AR,
};

export function legalLocaleFromPathname(pathname: string | null | undefined): LegalLocale {
  const path = pathname ?? "/";
  if (path === "/en" || path.startsWith("/en/")) return "en";
  if (path === "/it" || path.startsWith("/it/")) return "it";
  if (path === "/nl" || path.startsWith("/nl/")) return "nl";
  if (path === "/es" || path.startsWith("/es/")) return "es";
  if (path === "/no" || path.startsWith("/no/")) return "no";
  if (path === "/ar" || path.startsWith("/ar/")) return "ar";
  return "fr";
}

export function siteLocaleForLegalLocale(locale: LegalLocale): "fr" | "en" | "es" | "it" | "nl" | "no" {
  return locale === "en" ||
    locale === "es" ||
    locale === "it" ||
    locale === "nl" ||
    locale === "no"
    ? locale
    : "fr";
}

export function legalDocumentForPathname(pathname: string | null | undefined): LegalDocumentKey | null {
  const path = (pathname ?? "/").replace(/\/$/, "") || "/";
  for (const locale of Object.keys(LEGAL_ROUTES) as LegalLocale[]) {
    for (const key of ["privacy", "terms", "legal"] as LegalDocumentKey[]) {
      if (LEGAL_ROUTES[locale][key].replace(/\/$/, "") === path) return key;
    }
  }
  return null;
}
